+
+    /// Group peaks are fixed for this frame, unlike probe precision targets.
+    pub(super) fn finish_scalefactors(&mut self, n: usize) {
+        self.peak_sf_base.fill(0.0);
+        self.safe_sf.fill(0);
+        for (b, &peak) in self.peaks.iter().enumerate().take(n) {
+            if peak > 0.0 {
+                self.peak_sf_base[b] = crate::engine::spectrum::SF_OFFSET as f32
+                    + 4.0 * crate::engine::det_math::log2(peak);
+                self.safe_sf[b] = enc_quant::sf_for_peak(peak, enc_quant::QUANT_SAFE);
+            }
+        }
+    }
+
+    /// Original zero-offset short SF expression with only peak terms cached.
+    pub(crate) fn raw_scalefactors(&self, target_q: &[f32; MAX_FLAT_SHORT], q: &mut QuantShort) {
+        let n = q.n_groups * q.n_sfb;
+        for (b, &target) in target_q.iter().enumerate().take(n) {
+            q.sf[b] = if q.coded[b] && target >= 1.0 && self.peaks[b] > 0.0 {
+                let sf =
+                    self.peak_sf_base[b] - (16.0 / 3.0) * crate::engine::det_math::log2(target);
+                (sf.round() as i32).max(self.safe_sf[b])
+            } else {
+                0
+            };
+        }
     }
 }
