+#[test]
+fn short_peak_scalefactors_preserve_boundaries_and_group_history() {
+    let mut cache = ShortAlloc::new();
+    for n_sfb in [12, 14, 15] {
+        let mut cached = QuantShort::new(n_sfb);
+        for bits in [0, 127, 85, 0] {
+            cache.grouping = Grouping::from_bits(bits);
+            cached.set_grouping(cache.grouping);
+            let n = cached.n_groups * n_sfb;
+            for (b, peak) in cache.peaks.iter_mut().enumerate() {
+                *peak = match (b + usize::from(bits)) % 6 {
+                    0 => 0.0,
+                    1 => -0.0,
+                    2 => f32::from_bits(1),
+                    3 => f32::MIN_POSITIVE,
+                    4 => 1.0,
+                    _ => 3e7,
+                };
+            }
+            cache.finish_scalefactors(n);
+            for target in [0.0, 0.99, 1.0, 1.01, 2048.0, 7600.0, 8191.0, f32::MAX] {
+                cached.coded.fill(true);
+                for (b, coded) in cached.coded.iter_mut().enumerate().take(n) {
+                    *coded = !b.is_multiple_of(7);
+                }
+                let mut reference = cached.clone();
+                let tq = [target; MAX_FLAT_SHORT];
+                cache.raw_scalefactors(&tq, &mut cached);
+                enc_quant::raw_scalefactors_short(&cache.peaks, &tq, 0, &mut reference);
+                assert_eq!(
+                    cached.sf, reference.sf,
+                    "n_sfb={n_sfb} grouping={bits} target={target}"
+                );
+            }
+        }
+    }
+}
